{"content":"#!/usr/bin/env node
// extract.js: extract 32-bit memory words from ELF PT_LOAD segments.
// Usage: node extract.js /app/a.out > out.json
// Outputs JSON object: { "<vaddr decimal>": <uint32 LE value>, ... }
const fs = require('fs');

function readU16(buf, off, le) {
  return le ? buf.readUInt16LE(off) : buf.readUInt16BE(off);
}
function readU32(buf, off, le) {
  return le ? buf.readUInt32LE(off) : buf.readUInt32BE(off);
}
function readU64(buf, off, le) {
  const v = le ? buf.readBigUInt64LE(off) : buf.readBigUInt64BE(off);
  return v;
}

function main() {
  const path = process.argv[2];
  if (!path) {
    console.error('Usage: node extract.js <binary>');
    process.exit(1);
  }
  const buf = fs.readFileSync(path);
  const out = {};
  try {
    if (buf.length < 64) { console.log(JSON.stringify(out)); return; }
    if (!(buf[0] === 0x7f && buf[1] === 0x45 && buf[2] === 0x4c && buf[3] === 0x46)) {
      console.log(JSON.stringify(out));
      return;
    }
    const eiClass = buf[4]; // 1 = 32-bit, 2 = 64-bit
    const eiData = buf[5];  // 1 = LE, 2 = BE
    const le = eiData !== 2;
    const is64 = eiClass === 2;

    let phoff, phentsize, phnum;
    if (is64) {
      phoff = Number(readU64(buf, 0x20, le));
      phentsize = readU16(buf, 0x36, le);
      phnum = readU16(buf, 0x38, le);
    } else {
      phoff = readU32(buf, 0x1c, le);
      phentsize = readU16(buf, 0x2a, le);
      phnum = readU16(buf, 0x2c, le);
    }
    if (!phentsize || !Number.isFinite(phoff)) { console.log(JSON.stringify(out)); return; }

    for (let i = 0; i < phnum; i++) {
      const h = phoff + i * phentsize;
      if (h + phentsize > buf.length) break;
      let pType, pOffset, pVaddr, pFilesz;
      if (is64) {
        pType = readU32(buf, h, le);
        // p_flags at h+4 (skip)
        pOffset = readU64(buf, h + 8, le);
        pVaddr = readU64(buf, h + 16, le);
        pFilesz = readU64(buf, h + 32, le);
      } else {
        pType = readU32(buf, h, le);
        pOffset = BigInt(readU32(buf, h + 4, le));
        pVaddr = BigInt(readU32(buf, h + 8, le));
        pFilesz = BigInt(readU32(buf, h + 16, le));
      }
      const PT_LOAD = 1;
      if (pType !== PT_LOAD) continue;
      const filesz = Number(pFilesz);
      const fileOff = Number(pOffset);
      const vaddr = pVaddr; // BigInt
      if (!Number.isFinite(filesz) || !Number.isFinite(fileOff)) continue;
      // Only full 4-byte words; ignore trailing partial bytes
      const nwords = Math.floor(filesz / 4);
      for (let w = 0; w < nwords; w++) {
        const fo = fileOff + w * 4;
        if (fo + 4 > buf.length) break;
        const val = le ? buf.readUInt32LE(fo) : buf.readUInt32BE(fo);
        const addr = (vaddr + BigInt(w * 4)).toString();
        out[addr] = val;
      }
    }
  } catch (e) {
    // On any parse error, output what we have (or empty)
  }
  console.log(JSON.stringify(out));
}

main();
